use std::collections::HashMap;
use std::fs::{self, OpenOptions};
use std::io::Write;

pub struct KvStore {
    data: HashMap<String, String>,
    wal_path: String,
}

impl KvStore {
    pub fn new(path: &str) -> Self {
        let mut store = KvStore {
            data: HashMap::new(),
            wal_path: format!("{}.wal", path),
        };
        let _ = store.load_wal();
        store
    }

    fn load_wal(&mut self) -> std::io::Result<()> {
        let content = fs::read_to_string(&self.wal_path)?;
        for line in content.lines() {
            let parts: Vec<&str> = line.splitn(3, ' ').collect();
            if parts.len() >= 2 {
                match parts[0] {
                    "SET" => { if parts.len() == 3 { self.data.insert(parts[1].to_string(), parts[2].to_string()); } }
                    "DEL" => { self.data.remove(parts[1]); }
                    _ => {}
                }
            }
        }
        Ok(())
    }

    pub fn get(&self, key: &str) -> Option<&str> {
        self.data.get(key).map(|s| s.as_str())
    }

    pub fn set(&mut self, key: &str, value: &str) {
        self.data.insert(key.to_string(), value.to_string());
        let mut file = OpenOptions::new().create(true).append(true).open(&self.wal_path).unwrap();
        writeln!(file, "SET {} {}", key, value).unwrap();
    }

    pub fn del(&mut self, key: &str) -> bool {
        let existed = self.data.remove(key).is_some();
        let mut file = OpenOptions::new().create(true).append(true).open(&self.wal_path).unwrap();
        writeln!(file, "DEL {}", key).unwrap();
        existed
    }

    pub fn flush(&self) -> std::io::Result<()> {
        let mut content = String::new();
        for (k, v) in &self.data {
            content.push_str(&format!("SET {} {}\
", k, v));
        }
        fs::write(&self.wal_path, content)
    }
}

