const MAX_KEYS: usize = 3;

#[derive(Debug, Clone)]
pub struct BTreeNode {
    pub keys: Vec<String>,
    pub values: Vec<String>,
    pub children: Vec<BTreeNode>,
    pub is_leaf: bool,
}

impl BTreeNode {
    fn new(is_leaf: bool) -> Self {
        BTreeNode { keys: Vec::new(), values: Vec::new(), children: Vec::new(), is_leaf }
    }
}

pub struct BTree { root: BTreeNode }

impl BTree {
    pub fn new() -> Self { BTree { root: BTreeNode::new(true) } }
    pub fn insert(&mut self, key: &str, value: &str) {
        if self.root.keys.len() == MAX_KEYS {
            let mut new_root = BTreeNode::new(false);
            let old_root = std::mem::replace(&mut self.root, BTreeNode::new(false));
            new_root.children.push(old_root);
            self.split_child(&mut new_root, 0);
            self.root = new_root;
        }
        self.insert_non_full(&mut self.root, key, value);
    }
    fn split_child(&self, parent: &mut BTreeNode, idx: usize) {
        let mid = MAX_KEYS / 2;
        let mut child = parent.children[idx].clone();
        let mut right = BTreeNode::new(child.is_leaf);
        right.keys = child.keys.split_off(mid + 1);
        right.values = child.values.split_off(mid + 1);
        if !child.is_leaf {
            right.children = child.children.split_off(mid + 1);
        }
        let mid_key = child.keys.pop().unwrap();
        let mid_val = child.values.pop().unwrap();
        parent.keys.insert(idx, mid_key);
        parent.values.insert(idx, mid_val);
        parent.children.insert(idx + 1, right);
    }
    fn insert_non_full(&self, node: &mut BTreeNode, key: &str, value: &str) {
        let mut i = node.keys.len();
        if node.is_leaf {
            node.keys.push(String::new());
            node.values.push(String::new());
            while i > 0 && key < node.keys[i - 1].as_str() {
                node.keys[i] = node.keys[i - 1].clone();
                node.values[i] = node.values[i - 1].clone();
                i -= 1;
            }
            node.keys[i] = key.to_string();
            node.values[i] = value.to_string();
        } else {
            while i > 0 && key < node.keys[i - 1].as_str() { i -= 1; }
            if node.children[i].keys.len() == MAX_KEYS {
                self.split_child(node, i);
                if key > node.keys[i].as_str() { i += 1; }
            }
            self.insert_non_full(&mut node.children[i], key, value);
        }
    }
    pub fn search(&self, key: &str) -> Option<&str> {
        self.search_node(&self.root, key)
    }
    fn search_node<'a>(&'a self, node: &'a BTreeNode, key: &str) -> Option<&'a str> {
        let mut i = 0;
        while i < node.keys.len() {
            if key == node.keys[i].as_str() { return Some(&node.values[i]); }
            if key < node.keys[i].as_str() { break; }
            i += 1;
        }
        if node.is_leaf { None } else { self.search_node(&node.children[i], key) }
    }
    pub fn range(&self, start: &str, end: &str) -> Vec<(&str, &str)> {
        let mut result = Vec::new();
        self.range_collect(&self.root, start, end, &mut result);
        result
    }
    fn range_collect<'a>(&'a self, node: &'a BTreeNode, start: &str, end: &str, result: &mut Vec<(&'a str, &'a str)>) {
        for i in 0..node.keys.len() {
            if !node.is_leaf { self.range_collect(&node.children[i], start, end, result); }
            if node.keys[i].as_str() >= start && node.keys[i].as_str() <= end {
                result.push((&node.keys[i], &node.values[i]));
            }
        }
        if !node.is_empty() { self.range_collect(node.children.last().unwrap(), start, end, result); }
    }
}

impl BTreeNode {
    fn is_empty(&self) -> bool { self.keys.is_empty() }
}

