#[derive(Debug, Clone, PartialEq)]
pub enum Query {
    Insert { key: String, value: String },
    Select { key: Option<String>, range: Option<(String, String)> },
    Delete { key: String },
}

pub struct QueryParser {
    input: Vec<char>,
    pos: usize,
}

impl QueryParser {
    pub fn new(input: &str) -> Self { QueryParser { input: input.chars().collect(), pos: 0 } }
    pub fn parse(&mut self) -> Result<Query, String> {
        self.skip_whitespace();
        let keyword = self.read_word().to_uppercase();
        match keyword.as_str() {
            "INSERT" => {
                self.skip_whitespace();
                let key = self.read_word();
                self.skip_whitespace();
                let value = self.read_word();
                Ok(Query::Insert { key, value })
            }
            "SELECT" => {
                self.skip_whitespace();
                if self.pos >= self.input.len() {
                    Ok(Query::Select { key: None, range: None })
                } else {
                    let word = self.read_word();
                    self.skip_whitespace();
                    if self.pos < self.input.len() {
                        let word2 = self.read_word();
                        Ok(Query::Select { key: None, range: Some((word, word2)) })
                    } else {
                        Ok(Query::Select { key: Some(word), range: None })
                    }
                }
            }
            "DELETE" => {
                self.skip_whitespace();
                let key = self.read_word();
                Ok(Query::Delete { key })
            }
            _ => Err(format!("Unknown keyword: {}", keyword)),
        }
    }
    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_whitespace() { self.pos += 1; }
    }
    fn read_word(&mut self) -> String {
        let start = self.pos;
        while self.pos < self.input.len() && !self.input[self.pos].is_whitespace() { self.pos += 1; }
        self.input[start..self.pos].iter().collect()
    }
}

