use std::collections::HashMap;

#[derive(Debug, Clone)]
pub enum TxState { Active, Committed, Aborted }

pub struct Transaction {
    pub id: u64,
    pub state: TxState,
    pub writes: HashMap<String, Option<String>>,
}

pub struct TransactionManager {
    store: HashMap<String, String>,
    transactions: Vec<Transaction>,
    next_id: u64,
}

impl TransactionManager {
    pub fn new() -> Self {
        TransactionManager { store: HashMap::new(), transactions: Vec::new(), next_id: 1 }
    }
    pub fn begin(&mut self) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.transactions.push(Transaction {
            id,
            state: TxState::Active,
            writes: HashMap::new(),
        });
        id
    }
    fn find_tx_mut(&mut self, id: u64) -> Option<&mut Transaction> {
        self.transactions.iter_mut().find(|t| t.id == id && matches!(t.state, TxState::Active))
    }
    pub fn set(&mut self, tx_id: u64, key: &str, value: &str) -> Result<(), String> {
        let tx = self.find_tx_mut(tx_id).ok_or("Transaction not active")?;
        tx.writes.insert(key.to_string(), Some(value.to_string()));
        Ok(())
    }
    pub fn get(&self, tx_id: u64, key: &str) -> Option<String> {
        if let Some(tx) = self.transactions.iter().find(|t| t.id == tx_id && matches!(t.state, TxState::Active)) {
            if let Some(v) = tx.writes.get(key) { return v.clone(); }
        }
        self.store.get(key).cloned()
    }
    pub fn commit(&mut self, tx_id: u64) -> Result<(), String> {
        let tx = self.transactions.iter_mut().find(|t| t.id == tx_id).ok_or("Transaction not found")?;
        let writes = std::mem::take(&mut tx.writes);
        tx.state = TxState::Committed;
        for (k, v) in writes {
            match v {
                Some(val) => { self.store.insert(k, val); }
                None => { self.store.remove(&k); }
            }
        }
        Ok(())
    }
    pub fn rollback(&mut self, tx_id: u64) -> Result<(), String> {
        let tx = self.transactions.iter_mut().find(|t| t.id == tx_id).ok_or("Transaction not found")?;
        tx.writes.clear();
        tx.state = TxState::Aborted;
        Ok(())
    }
}

