use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::thread;

use crate::transaction::TransactionManager;

pub struct Server {
    tm: TransactionManager,
}

impl Server {
    pub fn new() -> Self { Server { tm: TransactionManager::new() } }
    pub fn start(&self, addr: &str) -> std::io::Result<()> {
        let listener = TcpListener::bind(addr)?;
        for stream in listener.incoming().flatten() {
            let tm = TransactionManager::new();
            thread::spawn(move || {
                let mut srv = Server { tm };
                srv.handle_client(stream);
            });
        }
        Ok(())
    }
    fn handle_client(&mut self, stream: TcpStream) {
        let mut reader = BufReader::new(&stream.try_clone().unwrap());
        let mut writer = stream;
        loop {
            let mut line = String::new();
            match reader.read_line(&mut line) {
                Ok(0) => break,
                Ok(_) => {
                    let line = line.trim();
                    let response = self.process_command(line);
                    writer.write_all(response.as_bytes()).ok();
                    writer.flush().ok();
                }
                Err(_) => break,
            }
        }
    }
    fn process_command(&mut self, line: &str) -> String {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() { return "-ERR empty command\\
".to_string(); }
        match parts[0].to_uppercase().as_str() {
            "PING" => "+PONG\\
".to_string(),
            "SET" if parts.len() == 3 => {
                let tx = self.tm.begin();
                self.tm.set(tx, parts[1], parts[2]).ok();
                self.tm.commit(tx).ok();
                "+OK\\
".to_string()
            }
            "GET" if parts.len() == 2 => {
                let tx = self.tm.begin();
                match self.tm.get(tx, parts[1]) {
                    Some(v) => format!("${}\\
{}\\
", v.len(), v),
                    None => "$-1\\
".to_string(),
                }
            }
            "DEL" if parts.len() == 2 => {
                let tx = self.tm.begin();
                self.tm.set(tx, parts[1], "").ok();
                self.tm.commit(tx).ok();
                "+OK\\
".to_string()
            }
            _ => "-ERR unknown command\\
".to_string(),
        }
    }
}
